def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    average = (v1 + v2) / 2

    return {
        "value": average,
        "trace": {
            "v1": v1,
            "v2": v2,
            "count": 2,
            "average": average,
            "output_meta": {
                "currency": "USD",
                "scale": "thousands",
                "unit": "currency"
            }
        }
    }
